def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(range(10), key=lambda c: sum(v == c for row in grid for v in row))
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx))
                        stack.append((ny,nx))
            comps.append((color, cells))

    # Use the distinctive non-background color with the largest connected
    # component as the paint color, then recolor the closest substantial object.
    by_color = {}
    for color, cells in comps:
        by_color[color] = max(by_color.get(color, 0), len(cells))
    paint = max(by_color, key=lambda c: by_color[c])
    marker = max((cells for color, cells in comps if color == paint), key=len)

    choices = []
    for color, cells in comps:
        if color == paint or len(cells) < 3:
            continue
        dist = min(abs(y-my) + abs(x-mx) for y, x in cells for my, mx in marker)
        choices.append((dist, -len(cells), color, cells))
    if not choices:
        return [row[:] for row in grid]

    _, _, _, target = min(choices)
    out = [row[:] for row in grid]
    for y, x in target:
        out[y][x] = paint
    return out
